/*
 * Collar and cuff styles from the shop's own pictures (24 Nov 2026), and a chest pocket option.
 * Three collars and two cuffs replace the earlier styles, which are hidden (old orders keep their names).
 * The pictures are stored as media, like photos uploaded in the admin, so they can be replaced there.
 */

insert into media (id, content_type, bytes, size) values ('00000000-0000-4000-a000-000000000c01', 'image/png', decode('', 'base64'), 10858) on conflict (id) do nothing;
insert into media (id, content_type, bytes, size) values ('00000000-0000-4000-a000-000000000c02', 'image/png', decode('', 'base64'), 11320) on conflict (id) do nothing;
insert into media (id, content_type, bytes, size) values ('00000000-0000-4000-a000-000000000c03', 'image/png', decode('', 'base64'), 10770) on conflict (id) do nothing;
insert into media (id, content_type, bytes, size) values ('00000000-0000-4000-a000-000000000f01', 'image/png', decode('', 'base64'), 7301) on conflict (id) do nothing;
insert into media (id, content_type, bytes, size) values ('00000000-0000-4000-a000-000000000f02', 'image/png', decode('', 'base64'), 9428) on conflict (id) do nothing;
insert into collars (id, name_en, name_ar, shape, image_url, sort, active) values ('wide-collar', 'Pointed collar', 'ياقة مدببة', 'wide-collar', '/v1/media/00000000-0000-4000-a000-000000000c01', 0, true)
  on conflict (id) do update set name_en = excluded.name_en, name_ar = excluded.name_ar, image_url = excluded.image_url, sort = excluded.sort, active = true;
insert into collars (id, name_en, name_ar, shape, image_url, sort, active) values ('classic-qatari', 'Band collar, two buttons', 'ياقة بزرين', 'classic-qatari', '/v1/media/00000000-0000-4000-a000-000000000c02', 1, true)
  on conflict (id) do update set name_en = excluded.name_en, name_ar = excluded.name_ar, image_url = excluded.image_url, sort = excluded.sort, active = true;
insert into collars (id, name_en, name_ar, shape, image_url, sort, active) values ('mandarin-band', 'Band collar, one button', 'ياقة بزر واحد', 'mandarin-band', '/v1/media/00000000-0000-4000-a000-000000000c03', 2, true)
  on conflict (id) do update set name_en = excluded.name_en, name_ar = excluded.name_ar, image_url = excluded.image_url, sort = excluded.sort, active = true;
insert into cuffs (id, name_en, name_ar, image_url, sort, active) values ('double', 'Double cuff (cufflinks)', 'كبك دبل (أزرار كبك)', '/v1/media/00000000-0000-4000-a000-000000000f01', 0, true)
  on conflict (id) do update set name_en = excluded.name_en, name_ar = excluded.name_ar, image_url = excluded.image_url, sort = excluded.sort, active = true;
insert into cuffs (id, name_en, name_ar, image_url, sort, active) values ('single', 'Single cuff', 'كبك عادي', '/v1/media/00000000-0000-4000-a000-000000000f02', 1, true)
  on conflict (id) do update set name_en = excluded.name_en, name_ar = excluded.name_ar, image_url = excluded.image_url, sort = excluded.sort, active = true;

-- Every other style is hidden from the counter and the app.
update collars set active = false where id not in ('wide-collar', 'classic-qatari', 'mandarin-band');
update cuffs set active = false where id not in ('double', 'single');

